import{_ as a,o as e,c as t,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Feature Workflow — spec → plan → task → test","description":"","frontmatter":{},"headers":[],"relativePath":"rule/feature-workflow.md","filePath":"rule/feature-workflow.md"}'),s={name:"rule/feature-workflow.md"};function o(i,n,h,d,l,p){return e(),t("div",null,[...n[0]||(n[0]=[c(`<h1 id="feature-workflow-—-spec-→-plan-→-task-→-test" tabindex="-1">Feature Workflow — spec → plan → task → test <a class="header-anchor" href="#feature-workflow-—-spec-→-plan-→-task-→-test" aria-label="Permalink to &quot;Feature Workflow — spec → plan → task → test&quot;">​</a></h1><p>&gt; Navigation: <a href="./../">← Knowledge Base Hub</a> · <a href="./README.html">← Rules Index</a> · <a href="./../feature/README.html">Feature Specs Hub →</a> &gt; &gt; <strong>Áp dụng cho toàn bộ các repo code trong hệ thống BrandHub:</strong> &gt; <code>brandhub-ai-service</code>, <code>brandhub-api-gateway</code>, <code>brandhub-business-service</code>, &gt; <code>brandhub-mobile-app</code>, <code>brandhub-publisher-service</code>, <code>brandhub-web</code>. &gt; &gt; File này là <strong>nguồn sự thật duy nhất</strong>. Mỗi repo khác chỉ có 1 pointer trỏ về đây &gt; (trong <code>CLAUDE.md</code> / <code>AGENTS.md</code>). Muốn sửa quy trình → sửa file này, không sửa từng repo.</p><h2 id="_1-muc-đich" tabindex="-1">1. Mục đích <a class="header-anchor" href="#_1-muc-đich" aria-label="Permalink to &quot;1. Mục đích&quot;">​</a></h2><p>Mọi tính năng phát triển trong hệ thống phải đi qua <strong>4 tài liệu tuần tự</strong> trước khi viết code. Điều này đảm bảo: đúng nghiệp vụ (khớp 141 FR và 6 Canonical Roles: <code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>), có kế hoạch rõ, có task phân rã, có test kiểm chứng — trước khi AI agent hoặc dev bắt tay vào làm. Tránh &quot;code mò&quot;, tránh làm lan man, tránh làm lại nhiều lần.</p><h2 id="_2-cau-truc-thu-muc-docs-feature-2-nhanh-chuan" tabindex="-1">2. Cấu trúc thư mục <code>docs/feature/</code> (2 nhánh chuẩn) <a class="header-anchor" href="#_2-cau-truc-thu-muc-docs-feature-2-nhanh-chuan" aria-label="Permalink to &quot;2. Cấu trúc thư mục \`docs/feature/\` (2 nhánh chuẩn)&quot;">​</a></h2><p><strong>Vị trí bắt buộc:</strong> tập trung tại <a href="./../feature/README.html">docs/feature/README.md</a> trong <code>brandhub-infrastructure</code>, <strong>không</strong> đặt phân tán trong <code>docs/feature/</code> của từng repo con (<code>brandhub-web</code>, <code>brandhub-mobile-app</code>, ...). Lý do: <code>brandhub-infrastructure</code> là nguồn sự thật duy nhất khi nhiều thành viên cùng phối hợp trên một tính năng liên quan nhiều microservice.</p><p>Thư mục <code>docs/feature/</code> được tổ chức sạch sẽ thành <strong>2 nhánh rõ ràng</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brandhub-infrastructure/docs/feature/</span></span>
<span class="line"><span>├── README.md</span></span>
<span class="line"><span>├── srs/                                     # Nhánh 1: 141 FR chuẩn của SRS (chia theo 9 domain)</span></span>
<span class="line"><span>│   ├── 01-authentication/                   # 3.2.1 – 3.2.9   (9 FRs)</span></span>
<span class="line"><span>│   ├── 02-profile/                          # 3.3.1 – 3.3.4   (4 FRs)</span></span>
<span class="line"><span>│   ├── 03-agency-workspace/                 # 3.4.1 – 3.4.26  (26 FRs)</span></span>
<span class="line"><span>│   ├── 04-media-package-campaign/           # 3.5.1 – 3.5.13  (13 FRs)</span></span>
<span class="line"><span>│   ├── 05-content-task-workflow/            # 3.6.1 – 3.6.35  (35 FRs)</span></span>
<span class="line"><span>│   ├── 06-ai-features/                      # 3.7.1 – 3.7.19  (19 FRs)</span></span>
<span class="line"><span>│   ├── 07-publishing-social/                # 3.8.1 – 3.8.15  (15 FRs)</span></span>
<span class="line"><span>│   ├── 08-subscription-billing/             # 3.9.1 – 3.9.6   (6 FRs)</span></span>
<span class="line"><span>│   └── 09-admin-functions/                  # 3.10.1 – 3.10.14 (14 FRs)</span></span>
<span class="line"><span>│       └── &lt;3-x-y-slug&gt;/                    # Vd: 3-2-1-sign-up/</span></span>
<span class="line"><span>│           ├── spec.md                      # Đặc tả nghiệp vụ — LÀM TRƯỚC</span></span>
<span class="line"><span>│           ├── plan.md                      # Kế hoạch triển khai kỹ thuật</span></span>
<span class="line"><span>│           ├── task.md                      # Phân rã công việc (checklist thực thi)</span></span>
<span class="line"><span>│           └── test.md                      # Kịch bản / test case kiểm chứng</span></span>
<span class="line"><span>└── modules/                                 # Nhánh 2: 26 module mở rộng / mobile hợp nhất (chia theo 8 nhóm)</span></span>
<span class="line"><span>    ├── 01-identity-gateway/</span></span>
<span class="line"><span>    ├── 02-agency-studio-plans/</span></span>
<span class="line"><span>    ├── 03-campaign-package-delivery/</span></span>
<span class="line"><span>    ├── 04-task-chat-vault/</span></span>
<span class="line"><span>    ├── 05-ai-rag-and-crawler/</span></span>
<span class="line"><span>    ├── 06-ai-media-and-video-studio/</span></span>
<span class="line"><span>    ├── 07-billing-publisher-and-observability/</span></span>
<span class="line"><span>    └── 08-mobile-application/</span></span>
<span class="line"><span>        └── &lt;kebab-case&gt;/                    # Vd: mobile-auth/, mobile-creator-upload/</span></span>
<span class="line"><span>            ├── spec.md</span></span>
<span class="line"><span>            ├── plan.md</span></span>
<span class="line"><span>            ├── task.md</span></span>
<span class="line"><span>            └── test.md</span></span></code></pre></div><ul><li><strong>Nhánh <a href="./../feature/srs/README.html"><code>docs/feature/srs/</code></a></strong>: Dành cho <strong>141 Functional Requirements (<code>3.2.1</code>–<code>3.10.14</code>)</strong> của baseline SRS, gom vào đúng 1 trong 9 domain (<code>01-authentication</code> đến <code>09-admin-functions</code>), đặt tên thư mục theo <code>&lt;3-x-y-slug&gt;</code> (kebab-case, tiếng Anh).</li><li><strong>Nhánh <a href="./../feature/modules/README.html"><code>docs/feature/modules/</code></a></strong>: Dành cho các module nền tảng dùng chung (cross-cutting), cải tiến UI/UX tổng thể, tích hợp hạ tầng hoặc luồng đặc thù trên <code>brandhub-mobile-app</code>, gom vào đúng 1 trong 8 thư mục chuyên đề (<code>01-identity-gateway</code> đến <code>08-mobile-application</code>) và đặt tên theo <code>&lt;kebab-case&gt;</code>.</li><li>Mỗi thư mục tính năng chứa đúng <strong>4 file bắt buộc</strong> (<code>spec.md</code>, <code>plan.md</code>, <code>task.md</code>, <code>test.md</code>), mỗi file có <strong>trách nhiệm duy nhất</strong>, không trộn lẫn.</li></ul><h2 id="_3-noi-dung-tung-file" tabindex="-1">3. Nội dung từng file <a class="header-anchor" href="#_3-noi-dung-tung-file" aria-label="Permalink to &quot;3. Nội dung từng file&quot;">​</a></h2><h3 id="spec-md-—-đac-ta-nghiep-vu" tabindex="-1"><code>spec.md</code> — Đặc tả nghiệp vụ <a class="header-anchor" href="#spec-md-—-đac-ta-nghiep-vu" aria-label="Permalink to &quot;\`spec.md\` — Đặc tả nghiệp vụ&quot;">​</a></h3><p>Trả lời <strong>LÀM CÁI GÌ và VÌ SAO</strong>. Đối chiếu trực tiếp với <a href="./../ba/README.html">Phân tích nghiệp vụ BA</a>.</p><p>Gồm: Objective, Canonical Actors (<code>Guest</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code>, <code>Admin</code>), User Story, Acceptance Criteria, UI/UX, API Contract, Error Handling, Edge Cases, UI States, Test Cases (sơ bộ), Definition of Done, Out of Scope.</p><p><strong>Với mọi feature có UI</strong> (<code>brandhub-web</code>, <code>brandhub-mobile-app</code>), <code>spec.md</code> BẮT BUỘC có thêm 2 mục sau trong Acceptance Criteria / UI States — không được bỏ qua:</p><ul><li><strong>Đa ngôn ngữ (i18n):</strong> liệt kê toàn bộ text hiển thị mới sẽ dùng key nào (namespace, vd <code>landing.features.demoLabel</code>), xác nhận key được thêm đồng thời vào <strong>cả</strong><code>vi.json</code> và <code>en.json</code> (key-parallel), không hardcode chuỗi tiếng Việt/Anh trong JSX/TSX.</li><li><strong>Light/Dark mode:</strong> xác nhận UI mới hoạt động đúng ở cả 2 theme — dùng token/biến theme hoặc class <code>dark:</code> variant sẵn có, không hardcode màu cố định (hex/rgb) không có cặp dark tương ứng. Nêu rõ nếu có màu đặc thù cần thêm token mới.</li></ul><p><code>plan.md</code> phải liệt kê các file i18n locale sẽ đổi; <code>task.md</code> phải có task riêng &quot;cập nhật <code>vi.json</code> + <code>en.json</code>&quot; và &quot;kiểm tra light/dark mode&quot;; <code>test.md</code> phải có test case xác nhận đổi ngôn ngữ không vỡ UI và chuyển theme không vỡ contrast/màu sắc.</p><h3 id="plan-md-—-ke-hoach-ky-thuat" tabindex="-1"><code>plan.md</code> — Kế hoạch kỹ thuật <a class="header-anchor" href="#plan-md-—-ke-hoach-ky-thuat" aria-label="Permalink to &quot;\`plan.md\` — Kế hoạch kỹ thuật&quot;">​</a></h3><p>Trả lời <strong>LÀM THẾ NÀO</strong>. Phân rã giải pháp kỹ thuật dựa trên spec: thành phần, repo/file chạm tới, DB schema thay đổi (xem <a href="./../database/README.html">Database Architecture</a>), luồng dữ liệu, thứ tự build, rủi ro.</p><h3 id="task-md-—-phan-ra-cong-viec" tabindex="-1"><code>task.md</code> — Phân rã công việc <a class="header-anchor" href="#task-md-—-phan-ra-cong-viec" aria-label="Permalink to &quot;\`task.md\` — Phân rã công việc&quot;">​</a></h3><p>Trả lời <strong>TỪNG BƯỚC CỤ THỂ</strong>. Checklist thực thi theo thứ tự, mỗi task nhỏ, độc lập, có thể tick. Mỗi task ánh xạ tới phần trong <code>plan.md</code>.</p><h3 id="test-md-—-kich-ban-kiem-chung" tabindex="-1"><code>test.md</code> — Kịch bản kiểm chứng <a class="header-anchor" href="#test-md-—-kich-ban-kiem-chung" aria-label="Permalink to &quot;\`test.md\` — Kịch bản kiểm chứng&quot;">​</a></h3><p>Trả lời <strong>KIỂM TRA GÌ</strong>. Kịch bản test theo Acceptance Criteria trong <code>spec.md</code> (đủ cả happy case và unhappy/edge case). Nêu test case, input, mong đợi. Dùng làm checklist pass/fail khi hoàn thành.</p><h2 id="_4-tuan-tu-bat-buoc" tabindex="-1">4. Tuần tự bắt buộc <a class="header-anchor" href="#_4-tuan-tu-bat-buoc" aria-label="Permalink to &quot;4. Tuần tự bắt buộc&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spec.md  →  plan.md  →  task.md  →  test.md  →  Đọc đủ 4 file &amp; triển khai code</span></span>
<span class="line"><span>   ①          ②           ③          ④                        ⑤</span></span></code></pre></div><ul><li><strong>①→④ phải hoàn thành theo đúng thứ tự</strong> trước khi ⑤ viết code.</li><li>Không được nhảy cóc: chưa có <code>spec.md</code> thì không viết <code>plan.md</code>; chưa có <code>plan.md</code> thì không tách <code>task.md</code>; chưa có <code>task.md</code> thì không viết <code>test.md</code>.</li><li>AI agent (hoặc dev) <strong>chỉ được bắt đầu code sau khi đã đọc đủ cả 4 file</strong>.</li></ul><h2 id="_5-vong-lap-khi-co-sai-sot" tabindex="-1">5. Vòng lặp khi có sai sót <a class="header-anchor" href="#_5-vong-lap-khi-co-sai-sot" aria-label="Permalink to &quot;5. Vòng lặp khi có sai sót&quot;">​</a></h2><p>Nếu trong lúc code (hoặc sau khi code, test fail) phát hiện <strong>sai nghiệp vụ / thiếu sót / hiểu sai yêu cầu</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        ┌─────────────  QUAY LẠI BƯỚC 1  ─────────────┐</span></span>
<span class="line"><span>        │                                             │</span></span>
<span class="line"><span>spec.md (sửa lại cho ĐÚNG) → plan.md (sửa lại) → task.md (sửa lại) → test.md (sửa lại) → code</span></span>
<span class="line"><span>   ①                                ②              ③                ④               ⑤</span></span></code></pre></div><ul><li><strong>Luôn sửa từ <code>spec.md</code> trước</strong> vì <code>spec.md</code> là gốc rễ của sai lệch (nếu ảnh hưởng nghiệp vụ chung cần thống nhất với cả nhóm và đồng bộ với <a href="./../ba/README.html">docs/ba/</a>).</li><li>Sau khi sửa <code>spec.md</code> → <strong>refactor lại lần lượt</strong> <code>plan.md → task.md → test.md</code> cho khớp <code>spec.md</code> mới.</li><li>Không được &quot;vá code&quot; lúc ⑤ rồi bỏ qua việc cập nhật 4 tài liệu. Tài liệu phải luôn phản ánh đúng code.</li></ul><h2 id="_6-quy-tac-cho-ai-agent-developer-khi-thuc-thi" tabindex="-1">6. Quy tắc cho AI Agent &amp; Developer khi thực thi <a class="header-anchor" href="#_6-quy-tac-cho-ai-agent-developer-khi-thuc-thi" aria-label="Permalink to &quot;6. Quy tắc cho AI Agent &amp; Developer khi thực thi&quot;">​</a></h2><ul><li>Đọc đủ 4 file (<code>spec.md</code>, <code>plan.md</code>, <code>task.md</code>, <code>test.md</code>) trước khi viết code.</li><li>Làm đúng theo thứ tự task trong <code>task.md</code>.</li><li>Sau khi code xong, chạy đối chiếu <code>test.md</code> để tự verify.</li><li>Nếu thấy <code>spec.md</code>/<code>plan.md</code> không khớp thực tế → <strong>dừng lại</strong>, báo nhóm, và làm theo vòng lặp mục 5, không tự ý đổi nghiệp vụ trong lúc code.</li><li>Commit và mở PR tuân thủ <a href="./git-commit-convention.html">Git Commit Convention</a>.</li></ul>`,31)])])}const g=a(s,[["render",o]]);export{u as __pageData,g as default};
